import clsx from 'clsx';
import React from 'react';
import { FormattedMessage, useIntl, type IntlShape } from 'react-intl';

import {
  suggestion,
  suggestionsEmptyState,
  suggestionsLoading,
} from './Suggestion.sty.js';
import { Suggestion } from './Suggestion.js';
import { SuggestionGroup } from './SuggestionGroup.js';
import {
  suggestionsOverlayCSS,
  suggestionsListCSS,
  suggestionsScrollContainerCSS,
} from './SuggestionsOverlay.sty.js';
import { ProgressCircle } from '../../../core/components/progress/ProgressCircle.js';
import type { WithChildren } from '../../../core/types/with-children.js';
import { Flex } from '../../../layouts-core/flex/Flex.js';
import { Surface } from '../../../layouts-core/surface/Surface.js';
import type { FilterFieldContextProps } from '../contexts/FilterFieldContext.js';
import { _useFilterFieldContext } from '../hooks/useFilterFieldContext.js';
import {
  defaultComparisonOperatorSuggestions,
  defaultLogicalOperatorSuggestions,
  defaultValueOperatorSuggestions,
} from '../language/filterfield-language.js';

function getSuggestionsContent(
  intl: IntlShape,
  autoSuggestions: FilterFieldContextProps['autoSuggestions'],
  children: FilterFieldSuggestionsProps['children'],
) {
  const {
    trailing,
    showLogicalOperatorSuggestions,
    showComparisonOperatorSuggestions,
    showValueSuggestions,
  } = autoSuggestions;

  const autosuggestionsAvailable =
    showLogicalOperatorSuggestions ||
    showComparisonOperatorSuggestions ||
    showValueSuggestions;

  if (
    React.Children.toArray(children).length === 0 &&
    !autosuggestionsAvailable
  ) {
    return (
      <li className={clsx(suggestion, suggestionsEmptyState)}>
        {intl.formatMessage({
          defaultMessage: 'No suggestions',
          id: 'PjDGLO7+f1/CNRR0',
          description: 'Filter field empty suggestions message.',
        })}
      </li>
    );
  }

  return (
    <>
      {children ?? null}
      {/* Render either logical operator (and / or) or comparison operator (=, !=, ...) suggestions. */}
      {(showLogicalOperatorSuggestions ||
        showComparisonOperatorSuggestions) && (
        <SuggestionGroup>
          {showLogicalOperatorSuggestions &&
            defaultLogicalOperatorSuggestions.map((suggestion) => (
              <Suggestion key={suggestion.value} {...suggestion} />
            ))}
          {showComparisonOperatorSuggestions &&
            defaultComparisonOperatorSuggestions.map((suggestion) => (
              <Suggestion key={suggestion.value} {...suggestion} />
            ))}
        </SuggestionGroup>
      )}
      {/* Render value operator (*, ?) suggestions. */}
      {showValueSuggestions &&
        defaultValueOperatorSuggestions.map((suggestion) => (
          <Suggestion
            key={suggestion.value}
            {...suggestion}
            trailing={trailing}
          />
        ))}
    </>
  );
}

export type FilterFieldSuggestionsProps = WithChildren & { loading?: boolean };

/** Compound component of the FilterField to apply suggestions. */
export const Suggestions = (props: FilterFieldSuggestionsProps) => {
  const { loading, children }: FilterFieldSuggestionsProps = props;

  const intl = useIntl();

  const { filterFieldId, autoSuggestions } = _useFilterFieldContext();

  return (
    <Surface className={suggestionsOverlayCSS} elevation="floating">
      <div className={suggestionsScrollContainerCSS}>
        <ul
          className={suggestionsListCSS}
          {...{
            id: `suggestions-${filterFieldId}`,
            role: 'listbox',
            'aria-expanded': true,
            'aria-label': intl.formatMessage({
              id: 'BAfEyw7BhyJX3dfC',
              defaultMessage: 'Suggestions',
              description: 'Aria label for the suggestions overlay',
            }),
          }}
        >
          {loading ? (
            <Flex
              justifyContent="start"
              px={8}
              py={6}
              className={suggestionsLoading}
            >
              <ProgressCircle size="small" aria-label="Loading suggestions" />
              <FormattedMessage
                id="313HlKgYmTnqRqJU"
                defaultMessage="Loading suggestions"
                description="Message shown when suggestions are currently loaded."
              />
            </Flex>
          ) : (
            getSuggestionsContent(intl, autoSuggestions, children)
          )}
        </ul>
      </div>
    </Surface>
  );
};

Suggestions.displayValue = 'FilterField.Suggestions';
